static void sha256_compress(uint32_t state[8], const uint8_t block[64]){
    uint32_t w[64];
    for(int i=0;i<16;i++) w[i]=(block[i*4]<<24)|(block[i*4+1]<<16)|(block[i*4+2]<<8)|block[i*4+3];
